<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#284b3b}h1{font-size:24px}.meta{color:#7a857b}table{width:100%;border-collapse:collapse;margin-top:20px}th{text-align:left;background:#eaf1e9;padding:10px 6px}td{border-bottom:1px solid #e4e9e2;padding:9px 6px}tr{page-break-inside:avoid}.totals{background:#f2f5ef;padding:14px;margin-top:20px;font-size:11px}</style></head><body><h1>CaisseFlow / Rapport de caisse</h1><p class="meta">Généré le {{ now()->format('d/m/Y H:i') }} · {{ $transactions->count() }} opérations · {{ config('caisse.currency') }}</p><p>Période : {{ request('from') ?: 'Début' }} — {{ request('to') ?: 'Aujourd’hui' }} · Filtre : {{ request('period', 'Toutes périodes') }} · Type : {{ request('type', 'Tous') }} · Recherche : {{ request('q', '—') }}</p>
